// Rename id -> case_id and force every value to a string.
// id is a reserved data table column name; the Data Table node would silently
// drop it (getAddRow deletes DATA_TABLE_SYSTEM_COLUMNS), losing the case label.
// Stringifying matters too: the CSV parser types 57.8 as a number and
// 2026-09-13 as a date, and a String column rejects nothing but keeps both
// readable to the eval workflow's Code node.
const COLUMNS = [
  'case_id',
  'bucket',
  'question',
  'as_of_date',
  'expected_tool',
  'expected_answer',
  'rubric_notes',
];

const out = [];
for (const item of $input.all()) {
  const src = { ...item.json, case_id: item.json.case_id ?? item.json.id };
  const row = {};
  for (const col of COLUMNS) {
    const v = src[col];
    row[col] = v === undefined || v === null ? '' : String(v);
  }
  out.push({ json: row });
}

if (out.length !== 30) {
  throw new Error(`expected 30 rows from evals/dataset.csv, got ${out.length}`);
}

return out;
